using Crown.Core;
using System.Text.Json.Nodes;

internal static class StageTwentyFiveSpecs
{
    private static void Assert(bool value,string text){if(!value)throw new Exception(text);}
    internal static GameState Fixture()
    {
        var s=StageTwentyOneSpecs.Fixture();s.Player.Technologies.UnionWith(EpochCatalog.All.Take(5).SelectMany(e=>e.Technologies));for(int i=0;i<5;i++)s.Player.EpochChoices[i]=0;return s;
    }
    private static void Step(GameState s){s.PendingEvent=null;Assert(Engine.EndTurn(s).Success,"Turn failed");}
    private static void Valid(GameState s)=>SaveGame.Deserialize(SaveGame.Serialize(s));
    private static (GameState S,City City,Unit Troop) Depot(UnitKind kind=UnitKind.Spearmen)
    {var s=Fixture();var c=s.Cities[0];c.Buildings.Add(FieldLogistics.Depot);c.MilitarySupplies=30;var u=Engine.AddUnit(s,0,c.Tile,kind);return(s,c,u);}
    private static (GameState S,City City,Unit Raider) Raid()
    {
        var s=Fixture();s.Relation(0,1).War=true;var c=s.Cities[1];c.Buildings.Add(FieldLogistics.Depot);c.MilitarySupplies=40;
        for(int x=18;x<=20;x++){var t=s.Tiles[12*s.Width+x];t.Owner=1;t.Road=true;t.RoadOwner=1;}
        var u=Engine.AddUnit(s,0,12*s.Width+18,UnitKind.Spearmen);s.InvalidateLogistics();return(s,c,u);
    }
    public static void Run(Action<string,Action> test)
    {
        test("Military depots require engineering and an extended campaign",()=>{var s=Fixture();var c=s.Cities[0];s.Player.Technologies.Remove("engineering");Assert(!Engine.SetProject(s,c.Id,FieldLogistics.Depot).Success,"Free technology");s.Player.Technologies.Add("engineering");Assert(Engine.SetProject(s,c.Id,FieldLogistics.Depot).Success,"Legal depot rejected");s.EpochCampaign=false;Assert(FieldLogistics.ProjectError(s,FieldLogistics.Depot)!=null,"Legacy depot allowed");});
        test("A depot consumes real construction production and starts with no invented stocks",()=>{var s=Fixture();var c=s.Cities[0];double upkeep=Engine.Economy(s,0).AdministrationCost;c.ProductionPaused=false;Engine.SetProject(s,c.Id,FieldLogistics.Depot);c.Production=139.9;Step(s);Assert(c.Buildings.Contains(FieldLogistics.Depot)&&c.MilitarySupplies==0&&c.SupplyAllocation==0&&Engine.Economy(s,0).AdministrationCost>=upkeep+2,"Construction or upkeep missing");Valid(s);});
        test("Quartermaster allocation changes no production immediately and rejects repeat changes atomically",()=>{var(s,c,u)=Depot();double stock=c.MilitarySupplies,work=c.Production;Assert(FieldLogistics.SetAllocation(s,c.Id,25).Success&&c.MilitarySupplies==stock&&c.Production==work,"Instant supplies");string before=SaveGame.Serialize(s);Assert(!FieldLogistics.SetAllocation(s,c.Id,50).Success&&SaveGame.Serialize(s)==before,"Repeated allocation accepted");});
        test("Supply manufacture subtracts the exact production it spends from ordinary construction",()=>{var s=Fixture();var c=s.Cities[0];c.Buildings.Add(FieldLogistics.Depot);c.ProductionPaused=false;c.Food=0;Engine.SetProject(s,c.Id,"treasury");FieldLogistics.SetAllocation(s,c.Id,50);var control=SaveGame.Deserialize(SaveGame.Serialize(s));control.Cities[0].SupplyAllocation=0;double prior=c.Production;Step(s);Step(control);Assert(c.MilitarySupplies>0&&Math.Abs(c.Production+c.MilitarySupplies*2-control.Cities[0].Production)<.00001,"Production duplicated or lost");Valid(s);});
        test("Full stocks return all unused production to the ordinary project",()=>{var s=Fixture();var c=s.Cities[0];c.Buildings.Add(FieldLogistics.Depot);c.MilitarySupplies=FieldLogistics.Capacity(s,c);c.ProductionPaused=false;c.Food=0;FieldLogistics.SetAllocation(s,c.Id,50);Engine.SetProject(s,c.Id,"treasury");var control=SaveGame.Deserialize(SaveGame.Serialize(s));control.Cities[0].SupplyAllocation=0;Step(s);Step(control);Assert(c.MilitarySupplies==FieldLogistics.Capacity(s,c)&&Math.Abs(c.Production-control.Cities[0].Production)<.00001,"Full stock consumed extra work");});
        test("District construction receives work before supply allocation without double spending",()=>{var s=Fixture();var c=s.Cities[0];c.Buildings.Add(FieldLogistics.Depot);c.ProductionPaused=false;c.Food=0;Engine.SetProject(s,c.Id,"treasury");Assert(Districts.Begin(s,c.Id,c.Tile+1,DistrictKind.Gardens,DistrictFunding.Public).Success&&Districts.SetShare(s,c.Id,50).Success,"District setup failed");FieldLogistics.SetAllocation(s,c.Id,50);var control=SaveGame.Deserialize(SaveGame.Serialize(s));control.Cities[0].SupplyAllocation=0;Step(s);Step(control);Assert(s.Districts.Single().Work==control.Districts.Single().Work&&c.MilitarySupplies>0&&Math.Abs(c.Production+c.MilitarySupplies*2-control.Cities[0].Production)<.00001,"District or depot double-spent production");Valid(s);});
        test("Pausing city production halts supply manufacture without deleting existing stocks",()=>{var(s,c,u)=Depot();s.Units.Clear();FieldLogistics.SetAllocation(s,c.Id,50);double stock=c.MilitarySupplies;Step(s);Assert(c.MilitarySupplies==stock,"Paused city manufactured stocks");});
        test("A full siege halts manufacture even with a funded unpaused depot",()=>{var(s,c,u)=Depot();s.Units.Clear();c.ProductionPaused=false;FieldLogistics.SetAllocation(s,c.Id,50);s.Relation(0,1).War=true;foreach(var t in World.Neighbors(s,c.Tile).Take(3))Engine.AddUnit(s,1,t.Id,UnitKind.Spearmen);double stock=c.MilitarySupplies;Step(s);Assert(c.MilitarySupplies==stock,"Encircled depot manufactured stocks");});
        test("Manual loading charges finite stocks movement and clears prior orders",()=>{var(s,c,u)=Depot();u.Destination=c.Tile+1;double moves=u.Actions;Assert(FieldLogistics.Refill(s,u.Id).Success&&u.SupplyReserve==3&&c.MilitarySupplies==27&&u.Actions==moves-1&&u.Destination==null&&u.Order==MilitaryOrder.None,"Loading cost wrong");Valid(s);});
        test("Heavy cavalry and artillery need two packs for each reserve turn",()=>{foreach(var kind in new[]{UnitKind.Cavalry,UnitKind.Catapult}){var(s,c,u)=Depot(kind);Assert(FieldLogistics.Refill(s,u.Id).Success&&u.SupplyReserve==3&&c.MilitarySupplies==24,"Heavy unit got cheap supplies");Valid(s);}});
        test("Scarce stocks load only affordable reserve turns without fractional supplies",()=>{var(s,c,u)=Depot(UnitKind.Catapult);c.MilitarySupplies=3.5;Assert(FieldLogistics.Refill(s,u.Id).Success&&u.SupplyReserve==1&&c.MilitarySupplies==1.5,"Fractional reserve or negative stocks");});
        test("Refill rejects missing stocks movement foreign control and civil units atomically",()=>{for(int mode=0;mode<6;mode++){var(s,c,u)=Depot();int owner=0;switch(mode){case 0:c.MilitarySupplies=.5;break;case 1:u.Actions=0;break;case 2:owner=1;break;case 3:u.Kind=UnitKind.Scout;break;case 4:u.SupplyReserve=3;break;case 5:u.EscortCaravanId=99;break;}string before=SaveGame.Serialize(s);Assert(!FieldLogistics.Refill(s,u.Id,owner).Success&&SaveGame.Serialize(s)==before,"Rejected loading mutated state");}});
        test("Blocked land routes prevent remote loading even near a depot",()=>{var(s,c,u)=Depot();u.Tile=c.Tile+2;foreach(var t in World.Neighbors(s,c.Tile))t.Terrain=Terrain.Mountain;s.InvalidateLogistics();Assert(FieldLogistics.RefillError(s,u)!=null,"Supplies crossed sealed mountain ring");});
        test("An ordinary turn automatically loads units in stable ID order without creating stocks",()=>{var(s,c,first)=Depot();c.MilitarySupplies=4;var heavy=Engine.AddUnit(s,0,c.Tile,UnitKind.Catapult);Step(s);Assert(first.SupplyReserve==3&&heavy.SupplyReserve==0&&c.MilitarySupplies==1,"Refill priority or conservation wrong");Valid(s);});
        test("Connected troops retain their carried reserve without ongoing stock consumption",()=>{var(s,c,u)=Depot();FieldLogistics.Refill(s,u.Id);double stock=c.MilitarySupplies;Step(s);Step(s);Assert(u.SupplyReserve==3&&c.MilitarySupplies==stock,"Connected reserve consumed daily");});
        test("Three carried rations protect an isolated army and then restore normal attrition",()=>{var(s,c,u)=Depot();FieldLogistics.Refill(s,u.Id);u.Tile=7*s.Width+29;u.Actions=0;s.InvalidateLogistics();Assert(!Logistics.HasSupplyLine(s,u)&&Engine.Supplied(s,u),"Cutoff fixture invalid");for(int i=0;i<3;i++){double hp=u.Health;u.Actions=0;Step(s);Assert(u.SupplyReserve==2-i&&u.Health==hp,"Reserve did not protect its full turn");}Assert(!Engine.Supplied(s,u),"Empty reserve still supplied army");u.Actions=0;double health=u.Health;Step(s);Assert(u.Health==health-5,"Attrition did not resume");Valid(s);});
        test("Carried supply does not fabricate a physical route or commercial connection",()=>{var(s,c,u)=Depot();FieldLogistics.Refill(s,u.Id);u.Tile=7*s.Width+29;s.InvalidateLogistics();Assert(Engine.Supplied(s,u)&&!Logistics.HasSupplyLine(s,u)&&Logistics.For(s,0).Costs[u.Tile]>Logistics.Range(s,0)&&Logistics.For(s,0).ConnectedCities.Count==1,"Reserve created supply infrastructure");});
        test("Embarked reserves neither refill nor consume and cannot supply their own carrier",()=>{var s=StageTwentyTwoSpecs.Fixture();var c=s.Cities[0];c.Buildings.Add(FieldLogistics.Depot);c.MilitarySupplies=20;var u=Engine.AddUnit(s,0,c.Tile,UnitKind.Spearmen);FieldLogistics.Refill(s,u.Id);var ship=Engine.AddUnit(s,0,13*s.Width+12,UnitKind.Ship,"carrack");Assert(SeaTransport.Embark(s,u.Id,ship.Id).Success,"Boarding failed");double stock=c.MilitarySupplies;c.Buildings.Remove(Navy.Port);s.InvalidateLogistics();Step(s);Assert(u.SupplyReserve==3&&c.MilitarySupplies==stock&&!Engine.Supplied(s,u)&&!Engine.Supplied(s,ship),"Cargo invented or spent naval supply");Valid(s);});
        test("A convoy raid forecast leaves stocks RNG and campaign unchanged",()=>{var(s,c,u)=Raid();string before=SaveGame.Serialize(s);var raid=FieldLogistics.PreviewRaid(s,u);Assert(raid.Error==null&&raid.CityId==c.Id&&raid.Destroyed==20&&raid.Loot==10&&SaveGame.Serialize(s)==before,"Raid forecast mutated or misquoted");});
        test("Executing a raid destroys finite stocks pays exact loot and preserves the road",()=>{var(s,c,u)=Raid();double gold=s.Player.Gold;int grievance=s.Relation(0,1).GrievanceB;Assert(FieldLogistics.Raid(s,u.Id).Success&&c.MilitarySupplies==20&&s.Player.Gold==gold+10&&u.Actions==0&&s.Tiles[u.Tile].Road&&s.Relation(0,1).GrievanceB>grievance,"Raid costs or destruction wrong");string before=SaveGame.Serialize(s);Assert(!FieldLogistics.Raid(s,u.Id).Success&&SaveGame.Serialize(s)==before,"Repeat raid accepted");Valid(s);});
        test("Raids cannot destroy or loot more than the target actually stores",()=>{var(s,c,u)=Raid();c.MilitarySupplies=7.5;double gold=s.Player.Gold;Assert(FieldLogistics.Raid(s,u.Id).Success&&c.MilitarySupplies==0&&s.Player.Gold==gold+3,"Phantom loot or stocks");});
        test("Defenders and destroyed road links protect the stockpile from remote raids",()=>{for(int mode=0;mode<2;mode++){var(s,c,u)=Raid();var t=s.Tiles[12*s.Width+19];if(mode==0)Engine.AddUnit(s,1,t.Id,UnitKind.Spearmen);else{t.Road=false;t.RoadOwner=-1;}string before=SaveGame.Serialize(s);Assert(!FieldLogistics.Raid(s,u.Id).Success&&SaveGame.Serialize(s)==before,"Raid bypassed route protection");}});
        test("Peaceful borders empty depots and unready raiders reject without side effects",()=>{for(int mode=0;mode<5;mode++){var(s,c,u)=Raid();switch(mode){case 0:s.Relation(0,1).War=false;break;case 1:c.MilitarySupplies=0;break;case 2:u.Actions=0;break;case 3:u.Kind=UnitKind.Settler;break;case 4:u.EscortCaravanId=99;break;}string before=SaveGame.Serialize(s);Assert(!FieldLogistics.Raid(s,u.Id).Success&&SaveGame.Serialize(s)==before,"Illegal raid changed campaign");}});
        test("A three-step depot requires current reconnaissance before a raid",()=>{var(s,c,u)=Raid();u.Tile=12*s.Width+17;s.Tiles[u.Tile].Owner=1;s.Tiles[u.Tile].Road=true;s.Tiles[u.Tile].RoadOwner=1;Assert(FieldLogistics.PreviewRaid(s,u).Error!=null,"Hidden depot leaked");Engine.AddUnit(s,0,11*s.Width+19,UnitKind.Scout);Assert(FieldLogistics.PreviewRaid(s,u).Error==null,"Actual recon did not enable raid");});
        test("Capture salvages half a depot and resets its policy within the new owner's capacity",()=>{var(s,c,u)=Depot();c.Owner=c.OriginalOwner=1;s.Factions[1].Technologies.UnionWith(EpochCatalog.All.SelectMany(e=>e.Technologies));for(int i=0;i<18;i++)s.Factions[1].EpochChoices[i]=0;c.MilitarySupplies=200;c.SupplyAllocation=50;c.LastSupplyPolicyTurn=s.Turn;s.Player.Technologies.Clear();s.Player.EpochChoices.Clear();ProvincialPolitics.Transfer(s,c,0);Assert(c.MilitarySupplies==Math.Min(100,FieldLogistics.Capacity(s,c))&&c.SupplyAllocation==0&&c.LastSupplyPolicyTurn==-1,"Capture created overflow or retained hostile policy");Valid(s);});
        test("AI builds and funds depots through actual project and economic turns",()=>{var s=Fixture();var f=s.Factions[1];f.Technologies.UnionWith(EpochCatalog.All.Take(5).SelectMany(e=>e.Technologies));for(int i=0;i<5;i++)f.EpochChoices[i]=0;var c=s.Cities[1];for(int i=0;i<3;i++)Engine.AddUnit(s,1,c.Tile,UnitKind.Spearmen);Step(s);Assert(c.Project==FieldLogistics.Depot,"AI never selected depot");c.ProductionPaused=false;c.Production=139.9;Step(s);Assert(c.Buildings.Contains(FieldLogistics.Depot)&&c.SupplyAllocation==25,"AI failed construction or policy");Step(s);Assert(c.MilitarySupplies+s.Units.Where(u=>u.Owner==1).Sum(u=>u.SupplyReserve*FieldLogistics.Weight(u))>0,"AI fabricated no real supply production");Valid(s);});
        test("Military AI raids an exposed supply road without controlling player orders",()=>{var s=Fixture();var c=s.Cities[0];c.Buildings.Add(FieldLogistics.Depot);c.MilitarySupplies=40;s.Relation(0,1).War=true;for(int x=12;x<=14;x++){var t=s.Tiles[12*s.Width+x];t.Road=true;t.RoadOwner=t.Owner=0;}var u=Engine.AddUnit(s,1,12*s.Width+14,UnitKind.Spearmen);Engine.RunMilitaryAi(s,1);Assert(c.MilitarySupplies==20&&u.Actions==0,"AI raid did not use real costs");string before=SaveGame.Serialize(s);Engine.RunMilitaryAi(s,0);Assert(SaveGame.Serialize(s)==before,"Player auto-controlled");Valid(s);});
        test("Current saves preserve stock policies carried reserves and deterministic future",()=>{var(s,c,u)=Depot();FieldLogistics.SetAllocation(s,c.Id,25);FieldLogistics.Refill(s,u.Id);u.Tile=7*s.Width+29;s.InvalidateLogistics();var copy=SaveGame.Deserialize(SaveGame.Serialize(s));Assert(copy.Version==SaveGame.CurrentVersion&&copy.Cities[0].MilitarySupplies==27&&copy.Units.Single().SupplyReserve==3,"New fields lost");for(int i=0;i<3;i++){Step(s);Step(copy);Assert(SaveGame.Serialize(s)==SaveGame.Serialize(copy),"Supply future diverged");}});
        test("V22 migration preserves a naval manifest without inventing reserves and backs up exact input",()=>{var s=StageTwentyTwoSpecs.Fixture();var ship=Engine.AddUnit(s,0,13*s.Width+12,UnitKind.Ship,"carrack");var u=Engine.AddUnit(s,0,s.Cities[0].Tile,UnitKind.Spearmen);SeaTransport.Embark(s,u.Id,ship.Id);var node=JsonNode.Parse(SaveGame.Serialize(s))!;node["Version"]=22;foreach(var c in node["Cities"]!.AsArray())foreach(string key in new[]{"MilitarySupplies","SupplyAllocation","LastSupplyPolicyTurn"})c!.AsObject().Remove(key);foreach(var v in node["Units"]!.AsArray())v!.AsObject().Remove("SupplyReserve");string old=node.ToJsonString();var loaded=SaveGame.Deserialize(old);Assert(loaded.Version==SaveGame.CurrentVersion&&loaded.Units.Single(v=>v.Id==u.Id).EmbarkedOnId==ship.Id&&loaded.Units.All(v=>v.SupplyReserve==0)&&loaded.Cities.All(c=>c.MilitarySupplies==0&&c.SupplyAllocation==0),"Migration fabricated supplies or lost cargo");string dir=Path.Combine(Path.GetTempPath(),"crown-supply-"+Guid.NewGuid());Directory.CreateDirectory(dir);string path=Path.Combine(dir,"campaign.crown");try{File.WriteAllText(path,old);SaveGame.Write(loaded,path);Assert(File.ReadAllText(path+".v22.bak")==old&&SaveGame.Read(path).Version==SaveGame.CurrentVersion,"Exact V22 backup missing");}finally{foreach(string file in new[]{path,path+".tmp",path+".v22.bak"})File.Delete(file);Directory.Delete(dir);}});
        test("Save validation rejects invalid reserves stocks allocation dates roles and old-format depots",()=>{for(int mode=0;mode<9;mode++){var(s,c,u)=Depot();switch(mode){case 0:u.SupplyReserve=4;break;case 1:u.SupplyReserve=-1;break;case 2:u.Kind=UnitKind.Scout;u.SupplyReserve=1;break;case 3:c.MilitarySupplies=-1;break;case 4:c.MilitarySupplies=FieldLogistics.Capacity(s,c)+1;break;case 5:c.SupplyAllocation=100;break;case 6:c.LastSupplyPolicyTurn=s.Turn+1;break;case 7:c.Buildings.Remove(FieldLogistics.Depot);break;case 8:s.Version=22;break;}bool rejected=false;try{Valid(s);}catch(InvalidDataException){rejected=true;}Assert(rejected,"Forged supply state accepted");}});
    }
}
